from taf.ul.objectmodelchecker.datamodel.scf.model import SCFFactory
from taf.ul.objectmodelchecker.datamodel.nidd.model import NiddManagedObject, NiddData, NiddParameter
from taf.ul.objectmodelchecker.report import CheckReport
from taf.ul.objectmodelchecker.datamodel.scf.model import SCFParameterList
import re


class ModelChecker(object):

    def check_scf_parameters_vs_nidd(self, product, domain, sw_release, scf_xml_path):
        """
        Verify parameters found in SCF managed objects with NIDD database.
        :param product: Product name in NIDD terms ie. NRBTS
        :param domain: Domain name in NIDD terms ie. 5GNB
        :param scf_xml_path: Path to xml file
        :param sw_release: Official name of Software Release ie. 5G18 or 5G18A etc. (For NIDD sw package resolving.)
        :return: CheckReport object with result status and error_data
        """
        check_report = CheckReport()
        scf_model = SCFFactory(scf_xml_path).get_scf_model()
        nidd_data = NiddData(
            domain=domain,
            product=product
        )

        for scf_managed_object in scf_model.managed_objects:
            sw_package_version = self.__get_sw_package_version(
                sw_release=sw_release,
                sw_version=scf_managed_object.version
            )

            # NIDD Managed Object "class" name is in last part of SCF Managed Object's "mocName" ie. "MRBTS/NRBTS"
            nidd_mo_class_name = scf_managed_object.moc_name.split("/")[-1]

            nidd_managed_obj_basic = NiddManagedObject(
                domain=domain,
                product=product,
                name=scf_managed_object.moc_name,
                class_name=nidd_mo_class_name,
                package_name=sw_package_version
            )
            nidd_managed_obj_basic.update_model_from_api()

            if nidd_managed_obj_basic.package_id not in nidd_data.packages:
                nidd_data.add_package(
                    name=nidd_managed_obj_basic.package_name,
                    package_id=nidd_managed_obj_basic.package_id
                )
                nidd_data.packages[nidd_managed_obj_basic.package_id].update()

            nidd_package_model = nidd_data.packages[nidd_managed_obj_basic.package_id]

            self._check_scf_object(
                scf_managed_object=scf_managed_object,
                nidd_managed_obj_basic=nidd_managed_obj_basic,
                nidd_package_model=nidd_package_model,
                check_report=check_report
            )

        return check_report

    def _check_scf_object(self, scf_managed_object, nidd_managed_obj_basic, nidd_package_model, check_report,
                          parent_object=None):
        """
        Starts pre-defined checks in order. Checks update the CheckReport object with error result in case of failure.
        [FDEV] To be done as plugins with possibility to choose checks

        :param scf_managed_object: SCFManagedObject based on data from SCF XML
        :param nidd_managed_obj_basic: NiddManagedObject based on basic data from NIDD Parameters JSON API
        :param nidd_package_model: NiddPackage based on data from Standard XML Report API NIDD
        :param check_report: CheckReport with overall check result
        :param parent_object: [Optional] In case SCF Object that we check has children, the children shall be checked
                                in relation to their parent.
        """
        if parent_object is None:
            scf_object_to_check = scf_managed_object
        else:
            scf_object_to_check = parent_object

        for scf_parameter in scf_object_to_check.parameters:
            self.__abbrv_exists_in_nidd(
                scf_parameter=scf_parameter,
                nidd_managed_obj_basic=nidd_managed_obj_basic,
                scf_managed_object=scf_managed_object,
                check_report=check_report
            )

            if parent_object is None:
                self.__top_parameter_is_not_child(
                    scf_parameter=scf_parameter,
                    scf_managed_object=scf_managed_object,
                    nidd_managed_obj_basic=nidd_managed_obj_basic,
                    nidd_package_model=nidd_package_model,
                    check_report=check_report
                )

            if isinstance(scf_parameter, SCFParameterList):
                self._check_scf_object(
                    scf_managed_object=scf_managed_object,
                    nidd_managed_obj_basic=nidd_managed_obj_basic,
                    nidd_package_model=nidd_package_model,
                    check_report=check_report,
                    parent_object=scf_parameter
                )
            else:
                self.__parameter_value_is_not_default_value(scf_parameter=scf_parameter,
                                                            scf_managed_object=scf_managed_object,
                                                            nidd_managed_obj_basic=nidd_managed_obj_basic,
                                                            nidd_package_model=nidd_package_model,
                                                            check_report=check_report)

            if parent_object is not None:
                self.__parent_parameter_is_correct(
                    scf_parameter=scf_parameter,
                    scf_parent_parameter=parent_object,
                    scf_managed_object=scf_managed_object,
                    nidd_managed_obj_basic=nidd_managed_obj_basic,
                    nidd_package_model=nidd_package_model,
                    check_report=check_report
                )

    def __abbrv_exists_in_nidd(self, scf_parameter, nidd_managed_obj_basic, scf_managed_object, check_report):
        check_desc = "Parameter abbreviation should exist in NIDD model"
        check_name = 'abbrv_exists_in_nidd'
        if scf_parameter.name not in nidd_managed_obj_basic.parameters:
            check_report.add_error(
                container=scf_managed_object.dist_name,
                check_name=check_name,
                parameter_name=scf_parameter.name,
                additional_check_info=check_desc
            )

    def __parent_parameter_is_correct(self, scf_parameter, scf_managed_object, nidd_managed_obj_basic,
                                      nidd_package_model, scf_parent_parameter, check_report):
        check_desc = "Child Parameter should be under NIDD defined parent parameter"
        check_name = "parent_parameter_is_correct"

        parent_managed_object = nidd_package_model.managed_objects.get(nidd_managed_obj_basic.class_name, None)
        if parent_managed_object is None:
            check_desc_failed_mo = "Requested managed object {} does not exist in NIDD Package data xml api"
            check_report.add_error(
                container=scf_managed_object.dist_name,
                check_name=check_name,
                parameter_name=scf_parameter.name,
                additional_check_info=check_desc_failed_mo.format(
                    nidd_managed_obj_basic.class_name
                )
            )
            return

        parent_object_nidd = parent_managed_object.parameters.get(scf_parent_parameter.name, None)

        if parent_object_nidd is None:
            check_desc_failed_parent = "Parent parameter of this parameter {} does not exist in managed object {}"
            check_report.add_error(
                container=scf_managed_object.dist_name,
                check_name=check_name,
                parameter_name=scf_parameter.name,
                additional_check_info=check_desc_failed_parent.format(
                    scf_parent_parameter.name,
                    parent_managed_object.class_name)
            )
            return

        if scf_parameter.name not in parent_object_nidd.parameters:
            check_report.add_error(
                container=scf_managed_object.dist_name,
                check_name=check_name,
                parameter_name=scf_parameter.name,
                additional_check_info=check_desc
            )

    def __get_sw_package_version(self, sw_release, sw_version):
        exclude_moc_name = ".*(?P<sw_package_version>{}.*)".format(sw_release)
        package_match = re.match(exclude_moc_name, sw_version)
        return package_match.group("sw_package_version")

    def __parameter_value_is_not_default_value(self, scf_parameter, scf_managed_object,
                                               nidd_managed_obj_basic, nidd_package_model,
                                               check_report):
        check_desc = "Parameter value should be default value in NIDD"
        check_name = "parameter_value_is_not_default_value"

        nidd_managed_object = nidd_package_model.managed_objects.get(nidd_managed_obj_basic.class_name, None)
        nidd_object = nidd_managed_object.parameters.get(scf_parameter.name)

        if nidd_object is not None:
            if nidd_object.default_value is not NiddParameter.NotLoaded:
                if scf_parameter.value != nidd_object.default_value:
                    check_report.add_error(
                        container=scf_managed_object.dist_name,
                        check_name=check_name,
                        parameter_name=scf_parameter.name,
                        additional_check_info=check_desc)

    def __top_parameter_is_not_child(self, scf_parameter, scf_managed_object, nidd_managed_obj_basic,
                                     nidd_package_model, check_report):
        check_name = 'top_parameter_is_not_child'
        check_desc = "Parameter {} of this managed object {} should not be directly under Managed Object"

        nidd_managed_object = nidd_package_model.managed_objects.get(nidd_managed_obj_basic.class_name)
        child_object = nidd_managed_object.parameters.get(scf_parameter.name)

        if child_object is None:
            check_report.add_error(
                container=scf_managed_object.dist_name,
                check_name=check_name,
                parameter_name=scf_parameter.name,
                additional_check_info=check_desc.format(
                    scf_parameter.name,
                    nidd_managed_object.class_name)
            )
